    29→        success:          bool;
    30→        error_code:       i32;
    31→        bytes_processed:  u64;
    32→    }
    33→
    34→    // 디렉토리 항목 (list_dir 반환값)
    35→    struct DirEntry {
    36→        name:   string;
    37→        is_dir: bool;
    38→        size:   u64;
    39→    }
