   170→    // === 경로 조작 헬퍼 ===
   171→
   172→    // dir과 file을 경로로 결합
   173→    // 예: join_path("/data", "config.json") → "/data/config.json"
   174→    func join_path(dir: string, file: string) -> string {
   175→        if len(dir) == 0 {
   176→            return file;
   177→        }
   178→        if len(file) == 0 {
   179→            return dir;
   180→        }
