// ============================================================================
// FreeLang Virtual Machine 모듈 - 바이트코드 실행 엔진
// ============================================================================
// 목표: ASM 코드제너레이터가 생성한 바이트코드를 실행하는 스택 기반 가상 머신 구현
// 원리:
//   1. 32개 레지스터 (r0-r31)와 512-entry 스택을 사용한 스택 기반 VM
//   2. 바이트코드는 i32 배열로 표현, 각 명령어는 opcode + operand로 구성
//   3. 플래그 레지스터는 CMP 결과를 저장 (0=zero, -1=neg, 1=pos)
//   4. vm_execute로 전체 실행, vm_step으로 단계별 실행 가능
// 구조:
//   - 에러 상수 정의 (VM_ERR_* 120-123)
//   - 주요 구조체 (VMContext, VirtualMachine)
//   - 공개 API (vm_new, vm_load_bytecode, vm_execute, vm_step, vm_push, vm_pop 등)
//   - 내부 헬퍼 (opcode 추출, 플래그 계산, 유효성 검사)
// ============================================================================

module vm {
    // === 에러 코드 ===
    const VM_OK:           i32 = 0;     // 정상 완료
    const VM_ERR_STACK:    i32 = 120;   // 스택 오버플로우/언더플로우
    const VM_ERR_REGS:     i32 = 121;   // 잘못된 레지스터 인덱스
    const VM_ERR_INVALID:  i32 = 122;   // 잘못된 명령어 또는 바이트코드
    const VM_ERR_OVERFLOW: i32 = 123;   // 레지스터 오버플로우

    // === 상수 ===
    const MAX_STACK:       i32 = 512;   // 스택 최대 엔트리 수
    const MAX_REGS:        i32 = 32;    // 레지스터 개수
    const MAX_FRAMES:      i32 = 16;    // 호출 스택 깊이 (CALL/RET용)

    // === ASM opcode 정의 ===
    const ASM_LOAD:    i32 = 1;         // LOAD: regs[dst] = imm
    const ASM_ADD:     i32 = 2;         // ADD: regs[dst] = regs[src1] + regs[src2]
    const ASM_SUB:     i32 = 3;         // SUB: regs[dst] = regs[src1] - regs[src2]
    const ASM_MUL:     i32 = 4;         // MUL: regs[dst] = regs[src1] * regs[src2]
    const ASM_DIV:     i32 = 5;         // DIV: regs[dst] = regs[src1] / regs[src2]
    const ASM_CMP:     i32 = 6;         // CMP: flags = sign(regs[src1] - regs[src2])
    const ASM_JMP:     i32 = 7;         // JMP: ip = addr
    const ASM_JZ:      i32 = 8;         // JZ: if flags == 0, ip = addr
    const ASM_CALL:    i32 = 9;         // CALL: push(ip), ip = addr
    const ASM_RET:     i32 = 10;        // RET: ip = pop()
    const ASM_PUSH:    i32 = 11;        // PUSH: push(regs[src])
    const ASM_POP:     i32 = 12;        // POP: regs[dst] = pop()

    // === 데이터 구조체 ===
    // VM 실행 컨텍스트
    struct VMContext {
        regs:    [i64];     // 32개 레지스터
        stack:   [i64];     // 512-entry 스택
        sp:      i32;       // 스택 포인터 (다음 쓸 위치)
        ip:      i32;       // 명령어 포인터
        flags:   i32;       // CMP 플래그 (0=zero, -1=neg, 1=pos)
    }

    // 가상 머신 인스턴스
    struct VirtualMachine {
        bytecode:      [i32];      // 바이트코드 배열
        bytecode_len:  i32;        // 바이트코드 길이
        ctx:           VMContext;  // 실행 컨텍스트
        error:         i32;        // 최근 에러 코드
    }

    // === 내부 헬퍼 함수 ===

    // 플래그 계산: a - b의 부호 반환
    // 반환: a > b → 1, a == b → 0, a < b → -1
    @inline
    func compute_flags(a: i64, b: i64) -> i32 {
        let diff = a - b;
        if diff > 0 {
            return 1;
        } else if diff == 0 {
            return 0;
        } else {
            return -1;
        }
    }

    // i32 배열에서 opcode 추출 (상위 비트에서 opcode 추출)
    @inline
    func extract_opcode(instr: i32) -> i32 {
        return (instr >> 24) & 0xFF;
    }

    // i32 배열에서 dst 오퍼랜드 추출
    @inline
    func extract_dst(instr: i32) -> i32 {
        return (instr >> 16) & 0xFF;
    }

    // i32 배열에서 src1 오퍼랜드 추출
    @inline
    func extract_src1(instr: i32) -> i32 {
        return (instr >> 8) & 0xFF;
    }

    // i32 배열에서 src2 오퍼랜드 추출
    @inline
    func extract_src2(instr: i32) -> i32 {
        return instr & 0xFF;
    }

    // i32 배열에서 imm(immediate) 값 추출
    @inline
    func extract_imm(instr: i32) -> i32 {
        return instr & 0xFFFFFF;
    }

    // === 공개 API ===

    // 새 가상 머신 인스턴스 생성
    func vm_new() -> VirtualMachine {
        let regs = make([i64], MAX_REGS);
        let stack = make([i64], MAX_STACK);
        let i = 0;

        // 레지스터 초기화
        for i = 0; i < MAX_REGS; i = i + 1 {
            regs[i] = i64(0);
        }

        // 스택 초기화
        for i = 0; i < MAX_STACK; i = i + 1 {
            stack[i] = i64(0);
        }

        let ctx = VMContext{
            regs:   regs,
            stack:  stack,
            sp:     0,
            ip:     0,
            flags:  0,
        };

        let vm = VirtualMachine{
            bytecode:      make([i32], 0),
            bytecode_len:  0,
            ctx:           ctx,
            error:         VM_OK,
        };

        return vm;
    }

    // 바이트코드 로드
    // bytecode: 로드할 i32 바이트코드 배열
    // len: 바이트코드 길이
    // 반환: VM_OK 또는 에러 코드
    func vm_load_bytecode(vm: *VirtualMachine, bytecode: [i32], len: i32) -> i32 {
        if len < 0 {
            vm.error = VM_ERR_INVALID;
            return VM_ERR_INVALID;
        }

        vm.bytecode = bytecode;
        vm.bytecode_len = len;
        vm.ctx.ip = 0;

        return VM_OK;
    }

    // 스택에 값 푸시
    // 성공: VM_OK, 스택 오버플로우: VM_ERR_STACK
    func vm_push(vm: *VirtualMachine, val: i64) -> i32 {
        if vm.ctx.sp >= MAX_STACK {
            vm.error = VM_ERR_STACK;
            return VM_ERR_STACK;
        }

        vm.ctx.stack[vm.ctx.sp] = val;
        vm.ctx.sp = vm.ctx.sp + 1;

        return VM_OK;
    }

    // 스택에서 값 팝
    // 반환: (값, VM_OK) 또는 (0, VM_ERR_STACK)
    func vm_pop(vm: *VirtualMachine) -> (i64, i32) {
        if vm.ctx.sp <= 0 {
            vm.error = VM_ERR_STACK;
            return (i64(0), VM_ERR_STACK);
        }

        vm.ctx.sp = vm.ctx.sp - 1;
        let val = vm.ctx.stack[vm.ctx.sp];

        return (val, VM_OK);
    }

    // 레지스터 값 조회
    // 성공: (값, VM_OK), 범위 초과: (0, VM_ERR_REGS)
    func vm_get_reg(vm: *VirtualMachine, reg_id: i32) -> (i64, i32) {
        if reg_id < 0 || reg_id >= MAX_REGS {
            vm.error = VM_ERR_REGS;
            return (i64(0), VM_ERR_REGS);
        }

        return (vm.ctx.regs[reg_id], VM_OK);
    }

    // 레지스터에 값 설정
    // 성공: VM_OK, 범위 초과: VM_ERR_REGS
    func vm_set_reg(vm: *VirtualMachine, reg_id: i32, val: i64) -> i32 {
        if reg_id < 0 || reg_id >= MAX_REGS {
            vm.error = VM_ERR_REGS;
            return VM_ERR_REGS;
        }

        vm.ctx.regs[reg_id] = val;
        return VM_OK;
    }

    // 반환값 조회 (r1 레지스터 반환)
    func vm_get_result(vm: *VirtualMachine) -> i64 {
        if 1 >= MAX_REGS {
            return i64(0);
        }
        return vm.ctx.regs[1];
    }

    // VM 상태 초기화
    func vm_reset(vm: *VirtualMachine) -> i32 {
        let i = 0;

        // 레지스터 초기화
        for i = 0; i < MAX_REGS; i = i + 1 {
            vm.ctx.regs[i] = i64(0);
        }

        // 스택 초기화
        for i = 0; i < MAX_STACK; i = i + 1 {
            vm.ctx.stack[i] = i64(0);
        }

        vm.ctx.sp = 0;
        vm.ctx.ip = 0;
        vm.ctx.flags = 0;
        vm.error = VM_OK;

        return VM_OK;
    }

    // 단일 명령어 실행
    // 성공: VM_OK, 실패: 에러 코드
    func vm_step(vm: *VirtualMachine) -> i32 {
        // IP가 바이트코드 범위를 벗어났는지 확인
        if vm.ctx.ip >= vm.bytecode_len {
            vm.error = VM_ERR_INVALID;
            return VM_ERR_INVALID;
        }

        let instr = vm.bytecode[vm.ctx.ip];
        vm.ctx.ip = vm.ctx.ip + 1;

        let opcode = extract_opcode(instr);
        let dst = extract_dst(instr);
        let src1 = extract_src1(instr);
        let src2 = extract_src2(instr);
        let imm = extract_imm(instr);

        // 범위 검사
        if dst >= MAX_REGS || src1 >= MAX_REGS || src2 >= MAX_REGS {
            vm.error = VM_ERR_REGS;
            return VM_ERR_REGS;
        }

        // opcode별 실행
        if opcode == ASM_LOAD {
            // LOAD: regs[dst] = imm (i32를 i64로 확장)
            vm.ctx.regs[dst] = i64(imm);
            return VM_OK;

        } else if opcode == ASM_ADD {
            // ADD: regs[dst] = regs[src1] + regs[src2]
            let val1 = vm.ctx.regs[src1];
            let val2 = vm.ctx.regs[src2];
            vm.ctx.regs[dst] = val1 + val2;
            return VM_OK;

        } else if opcode == ASM_SUB {
            // SUB: regs[dst] = regs[src1] - regs[src2]
            let val1 = vm.ctx.regs[src1];
            let val2 = vm.ctx.regs[src2];
            vm.ctx.regs[dst] = val1 - val2;
            return VM_OK;

        } else if opcode == ASM_MUL {
            // MUL: regs[dst] = regs[src1] * regs[src2]
            let val1 = vm.ctx.regs[src1];
            let val2 = vm.ctx.regs[src2];
            vm.ctx.regs[dst] = val1 * val2;
            return VM_OK;

        } else if opcode == ASM_DIV {
            // DIV: regs[dst] = regs[src1] / regs[src2]
            let val1 = vm.ctx.regs[src1];
            let val2 = vm.ctx.regs[src2];
            if val2 == 0 {
                vm.error = VM_ERR_INVALID;
                return VM_ERR_INVALID;
            }
            vm.ctx.regs[dst] = val1 / val2;
            return VM_OK;

        } else if opcode == ASM_CMP {
            // CMP: flags = sign(regs[src1] - regs[src2])
            let val1 = vm.ctx.regs[src1];
            let val2 = vm.ctx.regs[src2];
            vm.ctx.flags = compute_flags(val1, val2);
            return VM_OK;

        } else if opcode == ASM_JMP {
            // JMP: ip = imm (주소로 점프)
            vm.ctx.ip = imm;
            return VM_OK;

        } else if opcode == ASM_JZ {
            // JZ: if flags == 0, ip = imm
            if vm.ctx.flags == 0 {
                vm.ctx.ip = imm;
            }
            return VM_OK;

        } else if opcode == ASM_CALL {
            // CALL: push(ip), ip = imm
            let err = vm_push(vm, i64(vm.ctx.ip));
            if err != VM_OK {
                vm.error = err;
                return err;
            }
            vm.ctx.ip = imm;
            return VM_OK;

        } else if opcode == ASM_RET {
            // RET: ip = pop()
            let addr, err = vm_pop(vm);
            if err != VM_OK {
                vm.error = err;
                return err;
            }
            vm.ctx.ip = i32(addr);
            return VM_OK;

        } else if opcode == ASM_PUSH {
            // PUSH: push(regs[src1])
            let val = vm.ctx.regs[src1];
            let err = vm_push(vm, val);
            if err != VM_OK {
                vm.error = err;
                return err;
            }
            return VM_OK;

        } else if opcode == ASM_POP {
            // POP: regs[dst] = pop()
            let val, err = vm_pop(vm);
            if err != VM_OK {
                vm.error = err;
                return err;
            }
            vm.ctx.regs[dst] = val;
            return VM_OK;

        } else {
            // 알 수 없는 opcode
            vm.error = VM_ERR_INVALID;
            return VM_ERR_INVALID;
        }
    }

    // 전체 바이트코드 실행 (RET까지 또는 bytecode_len 도달)
    func vm_execute(vm: *VirtualMachine) -> i32 {
        let err = VM_OK;

        while vm.ctx.ip < vm.bytecode_len {
            err = vm_step(vm);
            if err != VM_OK {
                return err;
            }

            // RET 명령어 실행 후 종료
            let current_ip = vm.ctx.ip - 1;
            if current_ip >= 0 && current_ip < vm.bytecode_len {
                let instr = vm.bytecode[current_ip];
                let opcode = extract_opcode(instr);
                if opcode == ASM_RET {
                    return VM_OK;
                }
            }
        }

        return VM_OK;
    }

    // 통계 정보를 문자열로 반환
    func vm_stats(vm: *VirtualMachine) -> string {
        let msg = "[VirtualMachine] ";
        msg = msg + "bytecode_len=" + i32_to_string(vm.bytecode_len);
        msg = msg + " ip=" + i32_to_string(vm.ctx.ip);
        msg = msg + " sp=" + i32_to_string(vm.ctx.sp);
        msg = msg + " flags=" + i32_to_string(vm.ctx.flags);
        msg = msg + " error=" + i32_to_string(vm.error);
        return msg;
    }

    // === 헬퍼 함수 ===

    // i32를 문자열로 변환
    @inline
    func i32_to_string(n: i32) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n == 3 { return "3"; }
        if n == 4 { return "4"; }
        if n == 5 { return "5"; }
        if n == 6 { return "6"; }
        if n == 7 { return "7"; }
        if n == 8 { return "8"; }
        if n == 9 { return "9"; }
        if n == 10 { return "10"; }
        if n == -1 { return "-1"; }
        if n == 120 { return "120"; }
        if n == 121 { return "121"; }
        if n == 122 { return "122"; }
        if n == 123 { return "123"; }
        return "?";
    }
}

